INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',409,'{"_type":"chat:Message","id":"8641420749:981","threadId":"telegram:8641420749","text":"Est-ce que tu as en memoire des contraintes hebdomadaires que tu prends en compte pour le planning hebdomadaire ? Si oui, on peut les supprimer car je n’ai aucune contrainte en ce moment. Est-ce que ca remet en cause le planning existant ? Doit-on l’adapter ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Est-ce que tu as en memoire des contraintes hebdomadaires que tu prends en compte pour le planning hebdomadaire ? Si oui, on peut les supprimer car je n’ai aucune contrainte en ce moment. Est-ce que ca remet en cause le planning existant ? Doit-on l’adapter ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":260,"offset":259}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":260,"offset":259}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":260,"offset":259}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-02T13:33:09.000Z","edited":false},"attachments":[],"isMention":false}',1786282387282);
