INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',411,'{"_type":"chat:Message","id":"8641420749:987","threadId":"telegram:8641420749","text":"Je veux que tu m’ecrives un rapport complet sur moi que je vais montrer a un coach d’ultra. Autznt l’historique, les objecticfs, le plan macro, le detail du plan de chaque semaine jusqu’à Marseille Napoli. Ca doit etre vraiment complet pour que le coach puisse avoir un vue complete etre nous donne du feedback si certaines choses peuvent etre ameliorees.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je veux que tu m’ecrives un rapport complet sur moi que je vais montrer a un coach d’ultra. Autznt l’historique, les objecticfs, le plan macro, le detail du plan de chaque semaine jusqu’à Marseille Napoli. Ca doit etre vraiment complet pour que le coach puisse avoir un vue complete etre nous donne du feedback si certaines choses peuvent etre ameliorees.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":356,"offset":355}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":356,"offset":355}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":356,"offset":355}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-02T13:37:16.000Z","edited":false},"attachments":[],"isMention":false}',1786282634219);
