INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',424,'{"_type":"chat:Message","id":"8641420749:1012","threadId":"telegram:8641420749","text":"Today’s ride /done. I had a light sensation on my right knee in the first Z3 block but nothing that made me think to stop. The sensation was right below the rotula, sensation in surface, between the top of the tibia and the bottom of the rotula. Then nothing during recup between blocks. During second block it was gradually increasing until 2/10 I wanted to see if it would disappear if I would continue but it wouldn’t. So I preferred not to insist and I stopped the second block half way. As soon as I was in Z2 again I didn’t feel anything, and also now that I finished nothing. I’m thinking of putting a bit of ice on the knee later on and that’s it. What’s your take?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Today’s ride /done. I had a light sensation on my right knee in the first Z3 block but nothing that made me think to stop. The sensation was right below the rotula, sensation in surface, between the top of the tibia and the bottom of the rotula. Then nothing during recup between blocks. During second block it was gradually increasing until 2/10 I wanted to see if it would disappear if I would continue but it wouldn’t. So I preferred not to insist and I stopped the second block half way. As soon as I was in Z2 again I didn’t feel anything, and also now that I finished nothing. I’m thinking of putting a bit of ice on the knee later on and that’s it. What’s your take?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":674,"offset":673}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":674,"offset":673}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":674,"offset":673}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","i