INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',470,'{"_type":"chat:Message","id":"8641420749:1124","threadId":"telegram:8641420749","text":"J’ai tappé mon genou droit sur un rocher en le baignant. Pile au milieu de la rotule. J’ai une toute petite plaie. Ca me fait peu mal mais c’est légèrement inflammé. J’ai du mal a plier la jambe. C’est certainement rien, juste une legere inflammation. Que faire ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai tappé mon genou droit sur un rocher en le baignant. Pile au milieu de la rotule. J’ai une toute petite plaie. Ca me fait peu mal mais c’est légèrement inflammé. J’ai du mal a plier la jambe. C’est certainement rien, juste une legere inflammation. Que faire ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":264,"offset":263}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":264,"offset":263}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":264,"offset":263}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-06T13:35:12.000Z","edited":false},"attachments":[],"isMention":false}',1786628112171);
